// pkg/util/paramtable/component_param.go line 822-835
p.MinPasswordLength = ParamItem{
	Key:          "proxy.minPasswordLength",
	DefaultValue: "6",
	Version:      "2.0.0",
	PanicIfEmpty: true,
}
p.MinPasswordLength.Init(base.mgr)

// pkg/util/paramtable/component_param.go line 847-858
p.MaxPasswordLength = ParamItem{
	Key:          "proxy.maxPasswordLength",
	DefaultValue: "72", // bcrypt max length
	Version:      "2.0.0",
	Formatter: func(v string) string {
		n := getAsInt(v)
		if n <= 0 || n > 72 {
			return "72"
		}
		return v
	},
}

// internal/proxy/util.go line 651-656
func ValidatePassword(password string) error {
	if len(password) < Params.ProxyCfg.MinPasswordLength.GetAsInt() || len(password) > Params.ProxyCfg.MaxPasswordLength.GetAsInt() {
		return merr.WrapErrParameterInvalidRange(Params.ProxyCfg.MinPasswordLength.GetAsInt(),
			Params.ProxyCfg.MaxPasswordLength.GetAsInt(),
			len(password), "invalid password length")
	}
	return nil
}
